export type PlatformStringKey = keyof typeof PLATFORM_STRINGS;

export function pt(locale: Locale, key: PlatformStringKey, vars?: Record<string, string | number>): string {
  let text: string = PLATFORM_STRINGS[key][locale === "ar" ? "ar" : "en"];
  if (vars) for (const [k, v] of Object.entries(vars)) text = text.split(`{${k}}`).join(String(v));
  return text;
}
